import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.Dp3tugkT.js";const p=JSON.parse('{"title":"Project Pitch: Distributed URL Shortener Engine","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),n={name:"00b-project-pitch.md"};function s(o,e,c,d,l,h){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="project-pitch-distributed-url-shortener-engine" tabindex="-1">Project Pitch: Distributed URL Shortener Engine <a class="header-anchor" href="#project-pitch-distributed-url-shortener-engine" aria-label="Permalink to &quot;Project Pitch: Distributed URL Shortener Engine&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><p>&quot;I built a high-performance URL shortening and telemetry platform using Express 5, MongoDB, React 19, and Redux Toolkit. It generates collision-resistant 7-character Nanoid slugs and vanity aliases, routing redirects via atomic click-tracking updates in MongoDB with zero race conditions. On the frontend, it uses TanStack Query for optimistic cache invalidation and TanStack Router for type-safe navigation, backed by an enterprise DAO pattern on the server that handles high concurrent redirect traffic effortlessly.&quot;</p><h2 id="_2-minute-comprehensive-pitch" tabindex="-1">2-Minute Comprehensive Pitch <a class="header-anchor" href="#_2-minute-comprehensive-pitch" aria-label="Permalink to &quot;2-Minute Comprehensive Pitch&quot;">​</a></h2><p>&quot;Link shortening appears deceptively simple on the surface, but building a production-grade system requires solving critical distributed systems challenges: collision-free slug generation, atomic analytics tracking under viral click storms, and sub-millisecond redirect latencies.</p><p>To address these demands, I architected this full-stack platform using Express 5 and modern ES modules. The backend implements a strict layered architecture separating routing, business logic in services, and data persistence via the Data Access Object pattern. When generating short links, the system leverages Nanoid with a 64-character URL-friendly alphabet across 7 characters, providing over 4.3 trillion unique combinations with negligible collision risk.</p><p>For link resolution, the service executes an atomic <code>findOneAndUpdate</code> operation with <code>$inc: { clicks: 1 }</code> against a unique B-Tree indexed field, ensuring click counts remain mathematically accurate even during concurrent traffic surges. On the frontend, I utilized React 19 paired with Redux Toolkit for synchronous client credentials and TanStack Query for managing server-state caching and background revalidation.</p><p>Security is integrated at every hop: passwords use salted bcrypt hashing, sessions are managed via httpOnly JWT cookies to prevent cross-site scripting exposure, and custom conflict error handlers gracefully catch vanity slug collisions. It is an architecture designed for high throughput, operational simplicity, and seamless horizontal scaling.&quot;</p>',8)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
